// Decide what to do from the form input and the currently existing Jobs.
// The repo allowlist is enforced here too (a form POST can be hand-crafted).
const REPOS = ["orazefabian/homecluster", "orazefabian/lang-learn-app"];
const IMAGE = 'ghcr.io/orazefabian/homecluster/claude-remote:0.2.0';

const form = $('Claude session form').first().json;
const action = form['Action'];
const repo = form['Repository'];
const branch = (form['Branch'] || '').trim();
const mode = form['Mode'] === 'privileged' ? 'privileged' : 'standard';

const jobs = ($('List session jobs').first().json.items || []);
const running = jobs.filter(j => !(j.status?.conditions || []).some(
  c => (c.type === 'Complete' || c.type === 'Failed') && c.status === 'True'));

if (action === 'Stop') {
  if (running.length === 0) return [{ json: { action: 'message', message: 'No session is running.' } }];
  return running.map(j => ({ json: { action: 'stop', name: j.metadata.name } }));
}

if (running.length > 0) {
  const j = running[0];
  return [{ json: { action: 'message', message:
    `A session is already running (${j.metadata.labels?.mode || 'standard'}: ${j.metadata.annotations?.['claude.halo/repo'] || j.metadata.name}). ` +
    'Find it at claude.ai/code, or submit again with Action = Stop.' } }];
}
if (!REPOS.includes(repo)) return [{ json: { action: 'message', message: `Repository ${repo} is not allowed.` } }];
if (branch && !/^[A-Za-z0-9_][A-Za-z0-9._\/-]{0,199}$/.test(branch)) return [{ json: { action: 'message', message: 'Invalid branch name.' } }];

const labels = { app: 'claude-session', mode };
const env = [
  { name: 'REPO', value: repo },
  { name: 'SESSION_MODE', value: mode },
  { name: 'GH_APP_ID', valueFrom: { secretKeyRef: { name: 'claude-session', key: 'APP_ID', optional: true } } },
  { name: 'GH_INSTALLATION_ID', valueFrom: { secretKeyRef: { name: 'claude-session', key: 'INSTALLATION_ID', optional: true } } },
  { name: 'GH_APP_PRIVATE_KEY_B64', valueFrom: { secretKeyRef: { name: 'claude-session', key: 'PRIVATE_KEY_B64', optional: true } } },
];
if (branch) env.push({ name: 'BRANCH', value: branch });

const job = {
  apiVersion: 'batch/v1',
  kind: 'Job',
  metadata: { generateName: 'claude-session-', namespace: 'claude-sessions', labels,
              annotations: { 'claude.halo/repo': repo } },
  spec: {
    backoffLimit: 0,
    ttlSecondsAfterFinished: 120,
    activeDeadlineSeconds: 28800,
    template: {
      metadata: { labels },
      spec: {
        serviceAccountName: mode === 'privileged' ? 'claude-session-admin' : 'claude-session',
        restartPolicy: 'Never',
        securityContext: { runAsNonRoot: true, runAsUser: 1000, runAsGroup: 1000, fsGroup: 1000,
                           seccompProfile: { type: 'RuntimeDefault' } },
        affinity: { nodeAffinity: {
          requiredDuringSchedulingIgnoredDuringExecution: { nodeSelectorTerms: [{ matchExpressions: [
            { key: 'kubernetes.io/hostname', operator: 'NotIn', values: ['halo-0'] }] }] },
          preferredDuringSchedulingIgnoredDuringExecution: [{ weight: 100, preference: { matchExpressions: [
            { key: 'kubernetes.io/hostname', operator: 'In', values: ['halo-1', 'halo-2'] }] } }] } },
        containers: [{
          name: 'claude',
          image: IMAGE,
          imagePullPolicy: 'IfNotPresent',
          stdin: true,
          tty: true,
          env,
          securityContext: { allowPrivilegeEscalation: false, capabilities: { drop: ['ALL'] } },
          resources: { requests: { cpu: '500m', memory: '1Gi' }, limits: { memory: '4Gi' } },
          volumeMounts: [{ name: 'home', mountPath: '/home/claude' }, { name: 'work', mountPath: '/work' }],
        }],
        volumes: [
          { name: 'home', persistentVolumeClaim: { claimName: 'claude-auth' } },
          { name: 'work', emptyDir: { sizeLimit: '10Gi' } },
        ],
      },
    },
  },
};
return [{ json: { action: 'start', job, repo, mode } }];
